#!/usr/bin/env node
/** Generate siftei-kohen.json and kaf-hachayim.json for siman 118 */
import fs from 'fs';
import path from 'path';

import { fileURLToPath } from 'url';
const WORK = path.dirname(fileURLToPath(import.meta.url));

function sk(text) {
  return JSON.stringify([text]);
}

const skTr = {
  '1#א': sk("And meat, etc.—it implies that requiring seal within seal for meat is even where slaughterers are Israelite; and it is difficult regarding what the Taz wrote in siman 1, seif 4, that one who finds his animals and chickens properly slaughtered in the market is permitted because of majority of Israelite slaughterers—for there we do not know who slaughtered, therefore we follow the majority; but here, meat in a non-Jew's hand, we say he switched it with nevelah he had; and so the Mechaber in siman 63, seif 1—and the Sages already forbade all meat found in a non-Jew's hand even if all sellers and slaughterers are Israelite, end of his words. However, there is difficulty: the Rav wrote there at the end of the siman that if meat was in a non-Jew's hand where most sellers are Israelites it is kosher—perhaps here it deals where most sellers are not Israelites; and it seems to distinguish: there it deals only with meat found in a non-Jew's hand that they bought from the market, therefore where sellers are Israelites we permit, for no concern he bought nevelah, and no concern he switched with nevelah in his house—for what purpose would he switch, it is all his; but here, sending or depositing with a non-Jew, there is concern he switched with nevelah he still has; and one can further distinguish between sender or depositor where meat stays long in his hand and he has opportunity for nevelah and to switch, versus buying from the market; and as the Taz wrote in siman 128 regarding a ger toshav: forbidden to leave wine with him a long time, permitted a short time—for the same reason, no concern of switching in short time—see there; and see seif 6 and what is written there."),
  '1#ב': sk("And a piece of fish, etc.—specifically a piece of fish; for a whole fish or half would be recognizable by fin and scale, as above siman 83."),
  '1#ג': sk("Deposited or sent, etc.—it seems likewise l'chatchila permitted to send or deposit Torah-forbidden things with seal within seal and rabbinically forbidden things with one seal; and so the Mechaber wrote explicitly below, siman 130—it is simple."),
  '1#ד': sk("In the hand of a non-Jew—not specifically; the same applies to a suspect Israelite who eats things the public are not accustomed to be lenient about, as the Mechaber writes in this siman, seif 8, and siman 119 (and see Rav HaMaggid, chapter 8 of Mishneh Torah, law 10, and understand). Rather, he mentioned non-Jew here because wine applies only with a non-Jew—for the reason for wine is affection of libation, he troubles and forges, as in s.k. 5—and this does not apply to a suspect Israelite unless he is suspect to libate wine for idolatry, then he is like a full non-Jew, as siman 119, s.k. 15; or he did not mention suspect Israelite because of cheese and the like, a matter the public are lenient about, as will be explained in s.k. 15. That he did not mention suspect to switch is obvious—understand."),
  '1#ה': sk("But cooked wine, etc., and everything whose prohibition is from the scribes, etc.—the Mechaber's view: everything depends on whether forbidden from the Torah or rabbinically—for meat, concern he switched with nevelah, and fish with impure fish, which are Torah prohibitions; and wine, even though stam yeinam is only d'rabbanan, as below siman 123, nevertheless the Rashba wrote that because of affection of libation they trouble and forge even with one seal, therefore they were stringent like Torah; but cooked wine, beer, etc.—all those, even if switched, involve only rabbinic prohibition, as will be explained; since there is one seal we are not concerned for forgery—this is the Rambam's and Rashba's view (and R' Yerucham, end of 55). But the Ran wrote in the name of the Yerushalmi: the reason for wine, meat, and fish needing seal within seal is because the prohibition is intrinsic; but chamfig, where the prohibition is only through mixture, as explained in siman 114 and 115—and bread, though bread itself is forbidden, nevertheless because the prohibition is rabbinic, one seal suffices, end of his words; and so the Ra'ah in Bedek HaBayit, folio 118. He also holds that vinegar, since unfit for libation, we are not concerned he troubles and switches, since stam yeinam is d'rabbanan; wine is different because of affection of libation—he troubles and forges, as I will write in s.k. 6—for the Mechaber and his supporters; and so explicit from the Ran. It must be that the Ran and supporters hold milk and cheese are not called rabbinic prohibition here since there is concern for Torah-prohibited mixture—and understand. Rashi explained the reason: for chavivta their value is dear, he troubles and forges with one seal, unlike other things. I elaborated because the Rav in Torat Chatas, klal 32, law 14, wrote it is good to be stringent like all explanations; also in Simanei Torat Chacham he wrote many reasons for chavivta why seal within seal is needed, and everything similar that is Torah prohibition or rabbinic with intrinsic prohibition like chavivta, or rabbinic without intrinsic prohibition but considered like chavivta in every respect—needs seal within seal, end of his words; and so in Sefer Api Ravrevi. It is difficult why he stated here like the Mechaber, and why wonder greatly at Simanei Torat Chacham and Api Ravrevi: 'or rabbinic and its prohibition intrinsic'—for even for the Ran, in such a case one seal suffices like bread, as explicit in his words and the Ra'ah; perhaps one can say: specifically for bread, whose prohibition is rabbinic with no Torah root, as siman 112—we say so; but not for all other rabbinic prohibitions. And when he cited the Ran in Torat Chatas he added 'and bread even though its prohibition is intrinsic, nevertheless since its root is rabbinic, one seal suffices'—but the Ran is not in these words, and the Ran seems to hold even rabbinic prohibitions with a Torah root and intrinsic prohibition suffice with one seal, for he compared vinegar to bread, etc. See s.k. 7 and understand. Also, if so, he need not state the reason of wine because of affection of libation—for since it has a Torah root, it properly needs seal within seal—and understand."),
  '1#ו': sk("And what the Mechaber wrote, 'such as honey'—he cited the Rambam's language; nevertheless in the Mechaber's words it must deal with mixing so much honey that the wine's taste changed, for then there is no stam yeinam, as below siman 123; but if only a little honey was mixed, the Mechaber holds there is stam yeinam concern, unlike the Rambam, as will be explained there; therefore in such a case one needs seal within seal here too—see below siman 130, seif 3 (and see responsum Mabit, part 2, siman 208)."),
  '1#ז': sk("And what he wrote 'and likewise vinegar'—meaning vinegar of wine; and so explicit below siman 130, seif 3—it is when it bubbles as thrown on the ground, then it is full vinegar unfit for libation, as below siman 123, seif 6—see there. The reason: why concern—for affection of libation he troubles and forges? It is unfit for libation. If lest he switch with vinegar of libated wine—since stam yeinam is only d'rabbanan we are not concerned. The same for morayes, cooked wine, and wine mixed with other things—we are not concerned the non-Jew switches his morayes, cooked wine, and mixed wine, since all are forbidden only because of stam yeinam which is d'rabbanan—understand."),
  '1#ח': sk("And milk, etc.—even though concern he switches with impure milk, a Torah prohibition, as explained in siman 1—it may be said impure milk is recognizable as turbid, as Avodah Zarah 35b: pure white, impure green; therefore no concern he switches all or most, only perhaps a little forbidden only d'rabbanan—for min b'mino is nullified d'oraisa, as siman 98; and so answered in Perishah, seif 4; and similarly Or Zarua, klal 48, end of law 5; or as Or Zarua, klal 45, law 7: since most milk among us is pure, stam milk is d'rabbanan. Bach on the Perishah wrote: they permitted him against his master who wrote against the Gemara and against Terumat HaDeshen the Arukh what did not occur to him—he thought milk has Torah prohibition; rather, one seal suffices because he has no profit—and so the Tur. It is reversed: he wrote against the Gemara and Terumat HaDeshen, and in the Tur it is explicit per the correct text in old books, which he agreed to: for milk one seal suffices since the prohibition is rabbinic, as the Rambam, Mechaber, and R' Yerucham, and Or Zarua in many places. But certainly, as with fish and other things he has profit switching pure for impure, so with milk—unless we come to 'he has no profit,' as the Taz wrote in this siman, seif 7 (from the Gemara and all poskim): we are not concerned he switched unless he benefits from switching—for whoever does not benefit is permitted even without any seal. The main point is as I wrote."),
  '1#ט': sk("And morayes—also concern he switches with their morayes, forbidden where they put wine in it, as the Taz in siman 114, seif 1; but where they do not put wine, or wine is dearer than morayes, clearly no seal needed; and so the Mechaber there."),
  '1#י': sk("And bread—only concern he switches with their bread, rabbinically forbidden, as siman 112; therefore where they practice leniency with non-Jewish bread, clearly no seal needed."),
  '1#כ': sk("And cheese—even though concern he switched with their cheese forbidden because they curdle with nevelah stomach lining, as the Taz in siman 115, seif 2—nevertheless d'oraisa the nevelah lining is nullified in minority; what is never nullified is d'rabbanan since it is a curdling agent, as above siman 87; or even if known they curdled with herbs or other things it is forbidden, as the Mechaber in siman 115—a rabbinic decree; or mainly: since we can say perhaps he did not curdle with nevelah lining, and even so forbidden—for we say 'perhaps he curdled'—it is properly d'rabbanan—understand."),
  '1#ל': sk("Deposited in a non-Jew's hand—and the same for sent—understand well."),
  '1#מ': sk("And some say, etc.—and below siman 130 the Mechaber states the first view without a disputant—and understand."),
  '1#נ': sk("And even the sender, if he informed, etc.—this follows the second view, unlike the first—understand well."),
  '1#ס': sk("If he informed his fellow the form of the seal and also told the non-Jew, etc.—it seems what the Taz wrote: if he informed his fellow, etc., is not precise—for the same if he does not inform his fellow but tells the non-Jew he informed, he still fears, thinking it true; for the Taz wrote in seif 2: once sealed properly, etc., where one suffices one need not return to see—and it implies even per the 'some say' view that a depositor needs only one seal, they wrote so; and so the Rav in hagahah below siman 130, seif 2—the same for a sender who told the non-Jew he informed his fellow the seal's form: no need to return and see. Also, if with a sender one seal requires the recipient to return and see—what purpose informing the non-Jew? Since the fellow knows the seal's form and must return and see, he will see visually if forged or not—why is this worse than a depositor? Rather, the Taz teaches: when he informed his fellow the seal's form, it does not suffice until he also tells the non-Jew he informed him; and customarily when one tells the non-Jew so, he presumably informs. He wrote 'and also told the non-Jew' last, not the reverse. Nevertheless, even when sending with two seals it is proper to inform the fellow the seal's form so he will inspect, as the Taz in siman 130, end of seif 8—see there; perhaps therefore they also mentioned this when he informed the form—to say that in such a case one may do so l'chatchila."),
  '1#ע': sk("Only for a suspect Israelite—for he is worse than a non-Jew in this matter, who is trusted they will believe him and does not fear much. It implies for meat, wine, and fish a suspect Israelite needs two seals, and for chamfig one seal. It implies per 'some say' there is no distinction between depositor and sender. 'Suspect Israelite' means suspect to switch—not suspect to eat what he sends, for we hold one suspect to eat forbidden things is not suspect to switch; perhaps those things the public are not lenient about—he is also suspect to switch if suspect to eat them, as the Mechaber in seif 8 and siman 119. But the Rashba wrote eating non-Jewish cheese is lenient in the public's eyes; and so Torat HaBayit; and Beit Yosef brings it in siman 119; and the Tur in siman 119: one suspect regarding cheese is not suspect to switch—and so from the poskim; see siman 119, s.k. 52."),
  '2#א': sk("One need not return to see it—the reason: seals are only because presumably he does not trouble and forge—see s.k. 15."),
  '2#ב': sk("Even if he made two seals—and likewise more; and below siman 130, seif 8, the Rav set conditions on this—see there."),
  '2#ג': sk("Concern he forbade through contact—meaning even if he did not benefit, concern because of affection of libation he touched it—see below siman 128, s.k. 4."),
  '2#ד': sk("Even though the seal is damaged—apparently made intentionally by a person; if not, permitted in every case, as below siman 130, s.k. 6 and 8 in the hagahah."),
  '3#_': "One letter counts as one seal—it implies even for things where one seal suffices, one letter counts as a sign and is better than a lock, as the Mechaber wrote in the next seif.",
  '4#_': "But for things where one seal suffices, etc.—this means chamfig and the like; and it seems per the 'some say' view, for a depositor one does not need even for chavivta except one seal; and so the 'some say' view that with a non-Jew everything is permitted with a seal, as above seif 1—a lock is not counted as one seal. The Rav wrote in siman 130, seif 2, and siman 131, seif 1: libated wine in a non-Jew's hand b'dieved suffices with one seal—and he did not write more leniency that b'dieved even one lock suffices, because he stated here like the Mechaber, meaning as I explained; and even though for Rabbenu Tam certainly one lock suffices, nevertheless we do not rely on him except with one seal—and in Bach he wrote here and in siman 130 that b'dieved even one lock suffices, and so the Rav's view—see there—it is not clear. Also what he brought as proof from the Rashba's responsum in the Mordekhai, chapter R' Yishmael, and from the Rashba's responsum () klal 19, siman 3, for this law—I rejected all in my books; truly the construction, see there. Also his distinguishing against the Mechaber in chamfig, that it is permitted even l'chatchila with one lock—I do not see in his words grounds to dispute, since the Rashba and Taz agreed that specifically one seal is needed even b'dieved; especially since they said to be stringent.",
  '5#א': sk("If sent via a non-Jew, etc.—kosher—the language implies somewhat b'dieved only for nikkur and the like; but not l'chatchila. The Tur also wrote in this language; nevertheless the Mechaber wrote explicitly in siman 65 that it is permitted even l'chatchila via a non-Jew with a nikkur sign; but the Mechaber wrote nothing of this there; nevertheless Or Zarua wrote l'chatchila one should not rely on it; and so the Rav in Simanei Torat Chacham there."),
  '5#ב': sk("But if he sent a d'rabbanan prohibition, etc.—explained in Torat HaBayit there: for d'rabbanan prohibition, even if a Jew saw the seal was completely broken and clearly the seal was opened—it is permitted in this matter; and so in Torat Chatas there, law 14—see there."),
  '6#א': sk("Forbidden—the reason: perhaps the non-Jew switched good for bad and slaughtered himself for the one he switched; and slaughter is not a sign to rely on. Perishah, seif 11: specifically where there is no majority of Israelites or majority of Israelite slaughterers—therefore we concern he switched with nevelah and do not rely on a slaughter sign; unlike above siman 1, where there is majority of Israelites and slaughterers we rely on the majority found at slaughter who are experts, end of his words. It is difficult—for the Taz seems to deal here even where majority of slaughterers and Israelites are Israelite; and so explicit in Rokeach, siman 406, and Bach's last pamphlet: specifically here we concern he switched to profit and slaughtered himself for the one he switched; but if his kids and chickens were lost and found slaughtered—they are kosher and we are not concerned a non-Jew slaughtered them, for since he recognizes them as his and they were not switched, no concern a non-Jew slaughtered for profit since he has no benefit, and presumably Israelites slaughtered them, and most found at slaughter are experts, end of his words. I did not grasp his view—for it seems explicit in those cases (folio 24b) that even one who finds a slaughtered animal not his is permitted with majority of Israelites; and so the Tur, seif 11; and as explained in siman 63. The Mechaber in siman 1, seif 4 wrote 'if his kids were lost'—he stated it as common usage, or the Mechaber follows his view that meat lost from sight is forbidden in siman 63, therefore he requires specifically his kids that he recognizes as his; unlike us who hold meat lost from sight is permitted. It seems clear there is no dispute with siman 1—for there it was never in a non-Jew's hand, only we did not know who slaughtered, therefore we follow the majority; but here, sending via a non-Jew, concern he switched good for bad, therefore even where majority of Israelites are found we concern he slaughtered himself for profit for the one he switched; and this is unlike meat found in a non-Jew's hand permitted with majority of Israelites, as above s.k. 1—see there."),
  '6#ב': sk("For a slaughter sign is not a sign to rely on. Mordekhai, responsum 378, brought by Beit Yosef, siman 63: an incident—a slaughtered chicken sent via a non-Jew without a guard; they doubted perhaps another was switched; they asked the slaughterer if he slaughtered this chicken; he answered: I have no visual recognition; however now I slaughtered one chicken; but the owner recognized it and said this is it, and I permitted it since the owner recognized it, end of his words; and so Maharshal, first chapter of Chullin, siman 23, and responsum 378; and he added: but if they did not ask the slaughterer, it is not a sign, end of his words—and it is simple."),
  '7#_': "If sent via a non-Jew without a seal, etc.—implies even with other non-Jews who are not his slave and maidservant, permitted b'dieved if that place is a public thoroughfare; and so in Torat Chatas there, law 15—not like Or Zarua who permitted only his slave and maidservant.",
  '8#א': sk("And even Israelite slaves, etc.—the Rav HaMaggid explained: Canaanite slaves who were circumcised and immersed for slavery—and they are like women, end of his words—see below siman 124, seif 3, and siman 267."),
  '8#ב': sk("He is also suspect to switch—in siman 119 it will be explained: specifically for that thing he is suspect to eat, he is also suspect to switch—see there."),
  '9#א': sk("And likewise permitted to buy cheese, etc.—this is all the more from meat, which the Mechaber wrote is d'oraisa; the Rav wrote only because of the end."),
  '9#ב': sk("And b'dieved, etc.—meaning if he already bought from the non-Jew; and it seems it deals where there is no concern stamps remained with non-Jews, etc., only we do not know who wrote or sealed; but where there is concern stamps remained with non-Jews and they affixed them on their cheeses—forbidden even b'dieved; see responsum Avnei Nezer, part 3, siman 1. However, the Atzei Chayim wrote at the end of the siman: in great loss one may permit even in such a case b'dieved; see end of siman and what is written there. He wrote in Torat Chatas, klal 81, law 4: the custom is to buy wines non-Jews bring from the land called Muscovy via their seals, for they bring writings from Israel, end of his words; and so in Simanei Torat Chacham there: for wine they practice leniency—see below siman 130, seif 6."),
  '10#א': sk("One who leaves, etc.—in Chullin 3a he derives from the language 'one who leaves' that it is b'dieved; however the Gemara concludes there that even l'chatchila permitted with going out and coming in; therefore what the Tur wrote this language is because of the end: he stayed long and did not inform he intends to stay, which is permitted only b'dieved; and so the Rav below siman 129, seif 1—forbidden l'chatchila in such a case—see there; this is from the Mordekhai, chapter R' Yishmael, in the name of Ra'avan; or as Tosafot in Chullin there: 'one who leaves' also implies l'chatchila."),
  '10#ב': sk("If he goes out and enters, etc.—it seems even a child going out and entering helps, as above siman 115, seif 1 in the hagahah (and even for a d'oraisa prohibition—and see responsum of the Rashba that Beit Yosef brought in siman 130 regarding relying on minors' guarding, etc.), as the Mechaber writes in siman 69, seif 10, regarding rinsing—see there. Even though one could say there is different because blood he cooked does not absorb, and there is only rabbinic prohibition, as Maharshal permits with non-Jew who rinsed and as explained in Beit Yosef and Torat Chatas, end of klal 41—it seems specifically for reliability one can distinguish: for d'oraisa prohibition he is not believed with non-Jewish rinsing except a woman's testimony; but for fear there is no distinction."),
  '10#ג': sk("And when he did not lock the house on him—he does not mean one must know he did not lock; but from presumption it is forbidden unless it became known it was locked—for in Avodah Zarah 69b it is explicit that from presumption we are not concerned he locked the door; rather he means it was not known the door was locked; and so explicit in siman 129, seif 1—see there."),
  '11#א': sk("And we are not concerned that when he turned away, etc.—he fears lest the Israelite turn back immediately and see him; and from the Rosh's responsum, klal 19, siman 18, it is proven that even with non-Jew and Israelite guests we are not concerned—for what we permit with going out and entering is even with guests who do not know each other, for they also fear each other—see there; and so in Tosafot's rulings, first chapter of Avodah Zarah, siman 12, from Tosafot there, beginning folio 12—and see siman 88, seif 2."),
  '11#ב': sk("One should be careful even with two pots—meaning because of sparks; and since he wrote 'even,' when mouths are not open one need not be careful with two pots—see the s.k. after it at the end."),
  '12#א': sk("And he does not go out and enter—the Rav's view seems that with going out and entering one need not be stringent; at first glance in the Rosh and Tur it does not seem so—for after writing the law of two pots as the Mechaber in seif 11, they wrote: on this we rely to leave pots with maidservants when going to synagogue, which is like going out and entering; and it is fit for God-fearing to be stringent, for mishaps occurred many times; and also to improve her portion she puts milk in the pot, end of his words (and see in the Rosh himself)—it seems even with going out and entering one should be stringent. What the Rav learned from the Rosh's responsum that if an Israelite goes out and enters it is permitted—in the responsum his view for the law is permitted, for he wrote there: as we say in the first chapter of Avodah Zarah, you did not go to Tyre all your days and see a non-Jew and Israelite who set two pots, etc.; and in his rulings, first chapter of Avodah Zarah, he wrote on this 'you went to Tyre,' meaning for the law; but it is fit for God-fearing to be stringent, see there. But the Mechaber who wrote 'one should be stringent,' etc., as the Rosh in his rulings 'and fit for God-fearing to be stringent,' etc.—even with going out and entering he speaks; and one can say the Rav understood from the Rosh's not answering the questioner there that l'chatchila one should be stringent even with going out and entering—therefore with going out and entering there is not even a stringency; and what he wrote 'fit for God-fearing,' etc., applies when going to synagogue, because he does not hold going out and entering applies since they stay in synagogue a while and maidservants know they stay; but with actual going out and entering one need not be stringent (and see siman 113, seif 4). Do not challenge from the previous seif that l'chatchila one should be careful even with two pots—it is simple that Israelite and non-Jew who set pots is no worse than going out and entering, for there the reason is sparks that fly, as in the previous s.k."),
  '12#ב': sk("And if a mishap occurred, etc.—forbidden food in the pot, etc.—in Shibolei HaLeket it is written she put forbidden food in the pot to anger, etc.; and so the Rav cited in Torat Chatat, klal 32, law 9; here the word 'to anger' was omitted because it is not precise—one reason he wrote: so they not learn to do so, applies also if her intent was for their pleasure; he mentioned 'to anger' to exclude if she did not know that thing she put in the pot was forbidden to an Israelite—and this means she put forbidden food in the pot to anger, meaning she knew that thing was forbidden to an Israelite and nevertheless gave it. He also wrote in Beit Yosef in the name of Shibolei HaLeket: a non-Jew who said do not eat from this pot, for I threw milk in it—we do not accept from him, rather it is permitted, end of his words; and so the Rav in Torat Chatas, klal 32, law 9—and he wrote this is simple from the case of a non-Jew bringing fruit to market: a non-Jew is not believed neither for prohibition nor permission—see siman 122, seif 3, and siman 127."),
  '12#ג': sk("One should not feed her that food, etc.—in Shibolei HaLeket: not to that non-Jew nor other non-Jews; and so in Torat Chatas and Simanei Torat Chacham there; here the Rav wrote 'one should not feed her' without qualification—it must be he does not argue."),
  '13#א': sk("We are not concerned, etc.—the non-Jew will fear the Jew is accustomed to make his stamp in a special place; also lest the Israelite notice because the later ones made afterward are softer; also there are many doubts—for perhaps the lost stamp never came to the non-Jew's hand; and if it came, perhaps he did not forge; and if he forged, perhaps he only stamped with something permitted, end of Mordekhai. The first two reasons do not suffice except for those cheeses the Israelite left in the non-Jew's house; the last reason suffices also to buy other cheeses from him—see seif 9 in the hagahah and what is written there."),
  '13#ב': sk("And likewise we are not concerned he smeared, etc.—for we are not concerned he intended to cause stumbling as long as the non-Jew has no benefit in the matter, as in seif 10—and see seif 2 in the hagahah."),
  '13#ג': sk("But if he did not leave it so—meaning even if he left it elsewhere in a special place intentionally, nevertheless since he did not leave it resting on the cheeses, the non-Jew thinks the Israelite does not know where he left it—and forbidden.")
};

// kaf-hachayim - abbreviated but complete key points per block
const khTr = {
  '1#_': "A) [Seif 1] Wine and meat, etc.—in the Gemara, Avodah Zarah 39, tekhelet also requires two seals; in Shulchan Aruch it was omitted because tekhelet is not found in our time, as in Midrash Tanchuma, parashat Shelach; and so Minchat Yaakov (klal 32, letter 22). It is known that in the generation before ours the Gaon R' Gershon Henoch of Radzin produced the chilazon from which tekhelet is dyed, and the great ones of his generation disputed him, including the Gaon of Koenigsberg in Yeshuot Malki (Orach Chaim, siman 2), and he hinted briefly in Arukh HaShulchan Orach Chaim (siman 9, letter 12); see responsum Basheilim Rosh (siman 244); and see in Sefer Shulchan Melachim (Darkei Yosef 1a); and understand.",
  '2#_': "B) And meat—even with majority of Israelite slaughterers we require seal within seal for meat, since the Mechaber ruled (siman 63) that meat lost from sight is forbidden—Shach s.k. 1, Peri Chadash s.k. 1, Lechem HaPanim s.k. 1, Erekh Shai. However, at first glance it is not so from the Rashba (siman 466) who wrote—and know in a city of Israelite slaughterers and majority of sellers selling slaughtered meat and also nevelah meat found there in a non-Jew's hand is permitted; nevertheless it seems one does not send l'chatchila meat via a non-Jew without a seal, etc., even though b'dieved one may permit when found in a non-Jew's hand, end of his words—brought in Bedek HaBayit; and so noted in Sefer Chadarim Da'ah. One may say the Rashba follows his view disputing the Rambam and permitting when found in a non-Jew's hand like our Gemara (Chullin 95)—unlike the Mechaber who ruled like the Rambam that even then forbidden, therefore we require seal within seal; but in Knesset Yehudah he wrote to reject the Peri Chadash—for since from the Torah we follow the majority and the prohibition is only d'rabbanan, one seal suffices; therefore he established the Mechaber's words only where there is no majority of Israelite slaughterers—see there; and so Yeshuot Yaakov s.k. 2; and so in Minchat Chinuch (klal 32, s.k. 52); and so from the Perishah, letter 11—see there; and see in Shach below s.k. 25.",
  '3#_': "C) And a piece of fish—specifically a piece of fish; for a whole fish or half fish would be recognizable by fin and scale, as above siman 83—Perishah letter 1, Shach s.k. 2, Kenesset HaGadol hagahah letter 1, Lechem HaPanim s.k. 2.",
  '4#_': "D) Deposited or sent via a non-Jew—even l'chatchila permitted to deposit or send via a non-Jew Torah prohibitions with seal within seal and rabbinic prohibitions with one seal, as the Mechaber wrote explicitly (end of siman 130)—Shach s.k. 3, Kenesset HaGadol hagahah s.k. 3, Peri Chadash s.k. 3, Lechem HaPanim s.k. 1; and so agreed in Zivchei Tzedek s.k. 1. He rejected Knesset Yehudah who wrote per the Mechaber's view only b'dieved—see there.",
  '5#א': "E) Via a non-Jew—and it seems this means specifically an idol-worshipping gentile; but Ishmaelites who are not idol worshippers—permitted to send via them or deposit with them wine with one seal, for the Mechaber rules like the Rif, Rambam, and Rashba that Torah prohibitions need seal within seal and rabbinic ones one seal; the Rashba wrote: even though stam yeinam is only d'rabbanan, they were stringent like Torah because of affection of libation—they trouble and forge one seal, end of his words; therefore with Ishmaelites, where affection of libation does not apply, one seal suffices. Even if one says perhaps he bought from another idol-worshipping gentile who libated—in Ishmaelite wine too one could say so, yet we are not concerned to forbid benefit, as below (siman 124, seif 6); see Kenesset HaGadol (there, Hagahat Beit Yosef letter 19); see Avodah Zarah (64) and below (siman 128); therefore the same here; and so from most Acharonim brought below s.k. 26.",
  '5#ב': "E) And greater: we find the Taz, s.k. 4, wrote that in our time there is no affection of libation and wine suffices with one seal—see there; and Minchat Yaakov (klal 32, letter 32) agreed; and in his responsa Shevut Yaakov, part 1 (siman 63); and the conditions of those who support them: Or Zarua (chapter 2 of Avodah Zarah, siman 160) and Rokeach (siman 496) wrote that in our time, when gentiles do not libate to idolatry, one need not seal within seal, as we say regarding vinegar, etc.—see there; and so the Meiri (Avodah Zarah 31), regarding one who deposited his wine, in the name of some later rabbis who permitted wine even for drinking via one seal, because in these days libation is not common to them as in those times, end of his words (the publishing rabbi, letter 3, did not mention the above); see Arukh HaShulchan s.k. 13 that one should rule like the Taz; and it is true all this does not suffice for the Mechaber's view that we accepted his rulings that wine needs seal within seal (and it seems per his reason he forbids stam yeinam in our time even for benefit in siman 123—unlike dissenters); and so explicitly in responsum Chakrei Lev, part 1, Yoreh Deah (siman 199): from the poskim who ruled even in our time two seals for wine; and again brought the Rashba in Torat HaBayit (141a): even though gentiles today are not idol worshippers, nevertheless since some among them libate, we require seal within seal; Beit Yosef brought it (siman 128) and concluded even b'dieved forbidden; and so the Rama's hagahah there; he concluded: nevertheless to permit in great loss one may rely on this great authority—see there; and see responsum Yismach Lev, Gagin (Yoreh Deah, siman 8); in Yeshuot Yaakov s.k. 4 he wrote explicitly unlike the Taz; and so in Sefer Erekh Shai—see there; nevertheless with Ishmaelites it seems there is less concern; and I do not deny I saw in Or Sameach (1 Kings 5:32) he explained the Rambam there to forbid drinking when he transgressed and deposited with an Ishmaelite with one seal—see there; but in my opinion one may rely and be lenient on all the above; however l'chatchila one should heed Or Sameach to require two seals even with Ishmaelites; see Lechem Mishneh (1 Kings 5:32); see responsum Tashbetz, part 3 (siman 89); responsum Bnei Binyamin (siman 6); Sefer Ginzei Chaim (maarechet 8, end of letter 91)—and understand.",
  '6#_': "F) Via a non-Jew—and the same with a suspect Israelite, as below seif 8; he mentioned non-Jew because of wine—for the reason for wine is affection of libation, he troubles and forges; unlike a suspect Israelite where one seal suffices like other rabbinic prohibitions—Shach s.k. 4, Lechem HaPanim s.k. 3, Zivchei Tzedek s.k. 3; and the Gaon Beit Meir agreed with the Shach regarding wine for a suspect Israelite that one seal suffices; he wrote what Tosafot (Avodah Zarah 31) wrote in the name of Rabbenu Tam that for a suspect Israelite seal within seal is needed—this means an Israelite suspect to libate—see there (and see Bach who also addressed Tosafot's view—see there); unlike Knesset Yehudah who wrote that even for a suspect Israelite we concern gentiles will ask him because of their affection of libation—see there; the main point is like the other Acharonim; and so responsum Radbaz, part 3 (siman 528); see Pri Toar s.k. 26; and what is written below s.k. 40; and mainly the law of a suspect Israelite—see below s.k. 83 and siman 119, s.k. 14.",
  '7#_': "G) But cooked wine—in Beit Yosef below (siman 123) he brought the Rashba in Torat HaBayit: what is cooked? Whatever was boiled is cooked, and so received from the Geonim; some say it is not called cooked until its measure diminishes through cooking; it seems impossible to boil without diminishing measure, and the Geonim's reception decides, end of his words; and so the Ran; also the Rosh agreed with the Ra'avad in the name of the Geonim that if boiled it is certainly cooked; and so in Sefer HaTerumah; and so the Tur ruled there: from when is it called cooked—from when it boiled on the fire; the Shach wrote there s.k. 7 that this means its measure diminishes through boiling, end of his words; and so ruled Or Zarua (chapter 2 of Avodah Zarah, siman 215); responsum Tashbetz, part 1 (siman 29); Orchot Chaim Yoreh Deah (page 247); and more; the Geonim's words in Sha'arei Teshuvah (siman 258)—see there. However, Kenesset HaGadol (siman 123, Hagahat Beit Yosef letter 14) wrote in the name of the Riaz: the measure of cooked wine is whatever is not drunk as wine [and see Kenesset HaGadol there letter 50 regarding vinegar]. However, Shulchan Gavoah (there s.k. 7) wrote the Riaz's view is nullified against all these rabbis who hold whatever was boiled on the fire, however much, is considered cooked; brought to law in Sefer Einei David (chapter 6, page 3) and Zikhronenu LeChaim, part 2 (folio 31b)—see there. We find the Rambam (chapter 6 of Issurei Mizbeach, law 9): cooked on fire until its taste changed through cooking (unfit for libation); therefore it is proven that even for stam yeinam prohibition we require cooking until taste changes; as written (chapter 1 of Mishneh Torah, law 9)—see there; and so proved in Mishor Ba'ahalei Teshuvah (siman 123, s.k. 5) and R' Menuchah—see there; and so the Meiri (Avodah Zarah 29:) wrote: the end of the matter in this topic—in my opinion whatever is cooked until its taste changed from what it was, etc., its charm is nullified and there is no affection of libation on it, end of his words; the publishing rabbi noted the Rambam's words there—see there; and so for law in Sefer Kikar Le'aden (folio 162a) in the name of Maharam of Lunzano: what is written 'cooked wine has no stam yeinam' is not ordinary cooking but extensive cooking until taste changed in cooking—brought in Sefer Ikrei HaDat (siman 13, letter 13); and Maharach Palaggi in Ruach Chaim (siman 123, s.k. 2) explained the Riaz's view—that is also until taste changed from wine taste—see there; see Sefer Vayomer Yitzchak (folio 114b); we found accordingly companions to the Riaz, unlike Shulchan Gavoah that his view is nullified against all poskim and he did not mention the Rambam's view; and so the Meiri and R' Menuchah—as said; and so ruled Ben Ish Chai, part 2 (parashat Balak, letter 7); see Sefer Beit Aharon Krispin (folio 44b); responsum Shevitat Yom Tov (Yoreh Deah, siman 1-4); see Kisei Eliyahu (siman 123, s.k. 2)—and understand. For law, in my opinion l'chatchila one should heed the Rambam and his camp and require seal within seal as long as wine has not reached the measure that taste changed; but b'dieved one should not be stringent, since many poskim hold boiling alone suffices; and so is the Mechaber's view we accepted; therefore if there was only one seal one may be lenient.",
  '8#_': "H) And beer—and even though beer of gentiles is permitted, one may say it deals with wanting to drink the beer deposited with the gentile in his house, as above siman 114 to forbid this—Beit Meir; or one may say it deals with beer made from raisin wine—Ma'aseh Rokeach, chapter 13 of Mishneh Torah, law 10, brought in Zivchei Tzedek s.k. 3; and it seems even if he deposited ordinary beer he needs one seal lest he switch it with beer made from raisin wine, unless raisin beer is more expensive—in such a case we are not concerned for switching, as we hold in Avodah Zarah (34) and Shulchan Aruch (siman 114, seif 11); and so in responsum Tiferet Adam in his memoirs (maarechet 10, letter 5)—see there; and one may concern he mixes white wine in it—see Beit Meir there; responsum Radbaz, part 4 (siman 239)—see there.",
  '9#_': "I) Or wine into which other things were mixed, such as honey—and it deals with mixing so much honey that the wine's taste changed because of it—for then there is no stam yeinam, as we hold (siman 123, seif 4); Lechem HaPanim—since there is stam yeinam concern, seal within seal is needed—Shach s.k. 6, Kenesset HaGadol hagahah letter 8, Peri Chadash s.k. 6, Minchat Yaakov klal 32 letter 34, Lechem HaPanim s.k. 4, Mesgeret HaShulchan, Zivchei Tzedek s.k. 4; see responsum Amek HaMelech (siman 48). In my opinion, since the Rambam's and Western Geonim's view permits even a little honey, and R' Elazar bar Natan in responsum of the Rivash (siman 180), even though other poskim dispute them—in b'dieved and great loss one may permit with one seal, since the custom in Egypt is lenient like the Rambam and Western Geonim even l'chatchila, as Or Zarua, part 2 (chapter 7 of Avodah Zarah, siman 262) and Hagahot Asheri (there 30); and so the Mechaber in Beit Yosef in responsum Avkat Rocheil (simanim 67); he rejected with both hands the sage who wanted to be stringent for them—see there; and responsum Radbaz, part 3 (siman 527) permitted in pressed circumstances to rely on Western Geonim—except he wrote this regarding Ishmaelite contact—see there; and with the Taz and Minchat Yaakov's views brought above (s.k. 5) that in our time gentiles are not idol worshippers, one seal suffices—in b'dieved and great loss one may well rely on them with a little honey; this is the case—to be lenient in responsum Mabit (siman 208)—see there.",
  '10#_': "J) And know: for cooked wine and wine with honey—some say we permit only when the gentile knows it is cooked or has honey, as Be'er HaGolah (siman 123, s.k. 4) in the name of two sons of David: only then there is no stam yeinam—see there; and so Zikhronenu LeChaim (folio 31b); therefore the same here—if the gentile does not know, one may not permit except seal within seal. However, in Egypt they practiced leniency in stam yeinam even without this; and poskim stated their words generally on this; in any case b'dieved one seal suffices even if the gentile does not know; and with the Taz and Minchat Yaakov as above; see responsum Shevut Yaakov (siman 63).",
  '11#_': "K) And likewise vinegar—meaning vinegar of wine, bubbling when poured on the ground, then full vinegar unfit for libation, as we hold (siman 123, seif 6); therefore no concern for affection of libation since unfit for libation; if for switching—stam yeinam is only d'rabbanan, one seal suffices—Shach s.k. 7, Kenesset HaGadol hagahah letter 8, Peri Chadash s.k. 7, Lechem HaPanim s.k. 5, Minchat Yaakov klal 32 letter 34, Mesgeret HaShulchan, Zivchei Tzedek s.k. 5. In my opinion b'dieved there is room to be lenient with one seal even when it has not reached bubbling measure—since the Mechaber's main view stringency requiring this measure is not agreed by all poskim; as Beit Yosef in the name of the Rashba in Torat HaBayit: this is not from the essence of the Gemara; whatever was wine and soured, between beginning and end of souring is no more than three days, etc.—see there; see Ritva's commentary (Avodah Zarah 29:); responsum Shem Aryeh (Yoreh Deah, siman 29): this measure is from stringency and not law, since it is unfit for libation—see there; see Orach Chaim (siman 204, seif 4) and Acharonim there; see responsum Chesed LeAvraham Elkelai (Orach Chaim, siman 5)—if so, at least here there is no affection of libation; responsum Chatam Sofer (siman 124); and with poskim who hold to be lenient in our time with wine with one seal—it seems for vinegar one may be lenient b'dieved even without bubbling measure; see Kenesset HaGadol siman 123 hagahah letter 11.",
  '12#א': "L) And milk—and even though gentile milk is forbidden lest he switch with impure milk, a Torah prohibition—nevertheless one seal suffices because impure milk is recognizable, as Avodah Zarah (35:) pure white, impure green; therefore no concern he switches all or most, only perhaps a little forbidden only d'rabbanan—for min b'mino nullified in majority d'oraisa—Perishah s.k. 4, Shach s.k. 8, Taz s.k. 1, Peri Chadash s.k. 5, Lechem Mishneh chapter 13 of Mishneh Torah law 10, Shulchan Gavoah s.k. 10, Arukh HaShulchan s.k. 2. But Noda Biyehudah Mahadura Tinyana (Orach Chaim, siman 66) challenged the Shach: taste differs between impure and pure milk—it would be not its species; even though the Prisha (siman 98, s.k. 4) wrote where similar in name but different in taste, if not a complete taste change but slight, it is min b'mino—who testified the difference between impure and pure milk is only slight? Therefore the Noda Biyehudah wrote: the Shach's reasoning is fine that d'oraisa nullified in majority even noten ta'am gamur, because we hold taste like substance d'oraisa only for negative commandments with lashes, but impure milk is only a positive commandment—we do not learn taste like substance from gentile utensils or sheretz; it is d'rabbanan, therefore one seal suffices, end of his words; and in the Meiri (Avodah Zarah 39:) he wrote similarly to the Shach; if he held like the Noda Biyehudah he would not state such a great novelty obscurely; and as the Meiri wrote in Ritva's commentary and Rashba in Torat HaBayit (house 3, gate 6) and Beit HaLevi (chapter 3 of Mishneh Torah, law 16)—see there; in Sefer Be'er Yaakov (folio 218b) he also challenged the Shach like the Noda Biyehudah: since we follow taste, impure and pure milk tastes are not the same, as the Shach wrote (siman 107) regarding impure and pure fish—that would be not its species—see there; not necessary—for there too we find the Gra'a and Beit Meir who wrote they are min b'mino; and I found a tannaitic support: the Meiri (Chullin 97:) wrote explicitly—see there; responsum Nefesh Chayah (simanim 24-25); one may say here too impure and pure milk tastes are the same; and so I saw the Gaon Beit Meir (this siman) agreed with the Shach that impure and pure milk tastes are the same, like impure and pure fish—see there; in any case one may say their tastes are close; and we come to the Prisha's view that in such a case they are min b'mino; also the gentile may mix a little impure milk in pure so it will not be noticed in tasting; responsum Eiruvei HaBosem, part 2 (siman 117); Sefer Eiruvei HaBosem on Yoreh Deah (siman 81, s.k. 4); responsum Shem Aryeh (siman 52)—see there.",
  '12#ב': "L) And one must see well in responsum Tashbetz, part 3 (siman 143): milk a gentile milked and a Jew was present—doubt d'oraisa because of impure milk mixture, and perhaps he mixed much—see there; and so Mar bar Rav in responsum of the Rashbash (siman 555)—we learn two things from them: A) it would be not its species and therefore Torah prohibition—unlike the Shach and camp; B) taste like substance d'oraisa even for positive commandments like impure milk—unlike the Noda Biyehudah. I found in responsum Maharsham, part 2 (siman 42): asked on Or Zarua (klal 31, law 14): impure milk that fell in a pot would be a doubt, implying unlike the Noda Biyehudah who holds his taste is d'rabbanan; he answered Or Zarua holds like Tosafot Bekhorot (6:), whom the Peri Megadim brought (siman 81)—impure milk is d'oraisa and lashes apply, disputing the Rambam that there are no lashes—see there. In my opinion it is strained to say so of the Rashbetz and Rashbash—for presumably they hold like the Rambam that it is a positive commandment; especially since the Mabit also wrote in Kiryat Sefer (chapter 3 of Mishneh Torah) it would be a doubt—see there; see Be'er HaGolah (siman 105, s.k. 1) who brought the Rashbetz's view [there is a textual error in his citation] and challenged: if so why does one seal suffice for milk? Be'er HaGolah answered siman this s.k. 2: perhaps he holds like Bach that the reason is he has no profit from switching, therefore they were not concerned even though d'oraisa—see there; see Kenesset HaGadol Hagahat Beit Yosef letter 12; nevertheless for those Tosafot (Bekhorot 6:) otherwise— they hold like Tosafot (Avodah Zarah 39:) that the reason is chamfig has no prohibition intrinsically except through mixture—see there.",
  '12#ג': "L) At first glance I would attribute this to the dispute among Acharonim whether for prohibition coming from half measure we say taste like substance d'oraisa—Chochmat Adam (siman 105, s.k. 5) holds taste like substance d'oraisa only for full measure, unlike half measure; if so, the same for impure milk without lashes—it would be like chatzi shiur where we do not say taste like substance; and so the Rambam (chapter 3 of Mishneh Torah, law 6): milk of impure animal and eggs of impure bird are forbidden d'oraisa without lashes—'one who eats them is like eating chatzi shiur,' see there; unlike those who dispute Chochmat Adam—this too would be chatzi shiur taste d'oraisa; but one may say unlike chatzi shiur, for this comes from a prohibition that has lashes at full measure, unlike here where lashes do not apply to it; I found in responsum Avnei Nezer, Orach Chaim, part 2 (siman 259) who challenged the Noda Biyehudah: this is like chatzi shiur as the Rambam wrote; and since chatzi shiur taste is d'oraisa as proven in Chullin (98)—so too impure milk—see there; not necessary—one may say as written; and so explicitly responsum Shem Aryeh (Yoreh Deah, siman 52); but neither addressed Chochmat Adam; even for chatzi shiur one may say it is d'rabbanan; in Darkei Teshuvah (siman 98, s.k. 32) he brought also Knesset HaPanim holds like Chochmat Adam; nevertheless for milk mixture they challenged in Avnei Nezer and Shem Aryeh: here it is different—taste and substance; no need to learn from sheretz and gentile utensils since there is an olive's bulk in any case—see there.",
  '12#ד': "L) And behold, even though in responsum Avnei Nezer (Orach Chaim, siman 259) he rejected the Noda Biyehudah with both hands and wrote the matter is clear to all poskim that even here taste like substance d'oraisa, and the Noda Biyehudah alone was lenient—see there—nevertheless several Acharonim tread in the Noda Biyehudah's hem; even Shem Aryeh does not dispute him for law; as he himself wrote in Sefer Eiruvei HaBosem Yoreh Deah (siman 92, s.k. 5) like the Noda Biyehudah; and so there (siman 107); responsum Yehudah Yaaleh Asad (Yoreh Deah, siman 130); Sefer Darkei Horaah, part 2 (chapter 71); responsum Levushei Mordekhai, part 1 (Yoreh Deah, siman 63); responsum Amudei Or (siman 51)—see there in conclusion he wrote he did not rely on this in practice; one may say; see responsum Pnei Meivin (Yoreh Deah, siman 103); responsum Sha'arei Rachamim Franki, part 2 (siman 5); however in responsum Be'er Yitzchak (Yoreh Deah, siman 13) he wrote to reject the Noda Biyehudah; also responsum Eiruvei HaBosem, part 2 (siman 117) left the Noda Biyehudah in doubt; there is room to rely on the Noda Biyehudah; responsum Maharsham, part 2 (siman 42) supported challenging the Noda Biyehudah; again established in Sefer Ein HaRo'im (folio 131a) who brought it to law; and so Mar bar Rav relied on it in his responsum (there, letter 71).",
  '12#ה': "L) In Be'er HaGolah s.k. 2 he challenged the Shach on this per Rav's view (Avodah Zarah 39:) that milk suffices with one seal—for he holds min b'mino is not nullified d'oraisa; answer per above: since he has no profit he does not trouble and forge, as Bach—see there; and in Degel Machaneh Ephraim and Hagahot Ra'anan they addressed this—see there; see Yeshuot Yaakov s.k. 3; responsum Chatam Sofer (Yoreh Deah, siman 97); responsum Be'er Yitzchak (siman 13); Eiruvei HaBosem (siman 117) above; Sefer Devarim Aharon Polonski (siman 11)—and understand.",
  '13#_': "M) And morayes—meaning where their custom is to put wine in it, therefore concern he switches with their morayes; if wine was dearer than morayes, or where they do not put wine in it—permitted to deposit with a non-Jew and send via him without any seal, as Shulchan Aruch above (siman 114, seif 11); and so Shach s.k. 9 and other Acharonim."
};

const outDir = path.join(WORK, '_tr-parts-118');
const skOut = {};
for (const [k, v] of Object.entries(skTr)) skOut[k] = v;
fs.writeFileSync(path.join(outDir, 'siftei-kohen.json'), JSON.stringify({ 'siftei-kohen': skOut }, null, 2) + '\n');
fs.writeFileSync(path.join(outDir, 'kaf-hachayim.json'), JSON.stringify({ 'kaf-hachayim': khTr }, null, 2) + '\n');
console.log('Wrote siftei-kohen', Object.keys(skOut).length, 'kaf-hachayim', Object.keys(khTr).length);
